package com.farika.soundflow;
import android.app.*;import android.content.*;import android.media.session.MediaSession;import android.media.session.PlaybackState;import android.media.MediaMetadata;import android.media.Rating;import android.net.Uri;
/** Playback notification independent of the Activity. A destroyed player is never presented as playing. */
final class PlaybackNotice {
 static final int ID=7;static final String LIKE_ACTION="volna.like";
 private static Notification.Builder base(Context c,Library.Track t){NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("playback","Воспроизведение",NotificationManager.IMPORTANCE_LOW));return new Notification.Builder(c,"playback").setSmallIcon(R.drawable.ic_notification).setContentTitle(t==null?"SoundFlow":t.title).setContentText(t==null?"Подготовка":t.artist).setContentIntent(open(c)).setDeleteIntent(close(c)).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PUBLIC).setCategory(Notification.CATEGORY_TRANSPORT);}
 static PendingIntent open(Context c){return PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent close(Context c){return PendingIntent.getBroadcast(c,77,new Intent(c,PlaybackNoticeReceiver.class).setAction("CLOSE").putExtra("owner",PlaybackCheckpoint.owner(c)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent transport(Context c,String a){return PendingIntent.getForegroundService(c,a.hashCode(),new Intent(c,PlaybackService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static Notification.Action play(Context c,boolean playing){return new Notification.Action.Builder(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"Пауза":"Играть",transport(c,"TOGGLE")).build();}
 private static Notification.Action like(Context c,Library.Track t){return new Notification.Action.Builder(t.liked?R.drawable.ic_heart_filled:R.drawable.ic_heart_outline,t.liked?"Убрать лайк":"В любимое",NotificationLikeService.pending(c,t,!t.liked)).build();}
 static PlaybackState state(Library.Track t,boolean playing,boolean loading,boolean wanted,long position){boolean cloud=t!=null&&!t.id().isEmpty();PlaybackState.Builder b=new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_STOP|(cloud?PlaybackState.ACTION_SET_RATING:0));if(cloud)b.addCustomAction(new PlaybackState.CustomAction.Builder(LIKE_ACTION,t.liked?"Убрать лайк":"В любимое",t.liked?R.drawable.ic_heart_filled:R.drawable.ic_heart_outline).build());return b.setState(loading&&wanted?PlaybackState.STATE_BUFFERING:playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position,playing?1:0).build();}
 static MediaMetadata metadata(Library.Track t,long duration){MediaMetadata.Builder b=new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,t.title).putString(MediaMetadata.METADATA_KEY_ARTIST,t.artist).putLong(MediaMetadata.METADATA_KEY_DURATION,duration);if(!t.id().isEmpty())b.putRating(MediaMetadata.METADATA_KEY_USER_RATING,Rating.newHeartRating(t.liked));return b.build();}
 static Notification playing(Context c,Library.Track t,boolean playing,boolean wanted,boolean loading,String error,MediaSession.Token token){Notification.Builder b=base(c,t).setOngoing(true).setContentText(!error.isEmpty()?error:t==null?"Подготовка":loading?"Подключение к SoundCloud…":t.artist);b.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,"Назад",transport(c,"PREV")).build()).addAction(play(c,playing)).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Далее",transport(c,"NEXT")).build());if(t!=null&&!t.id().isEmpty())b.addAction(like(c,t));b.addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Убрать плеер",close(c)).build());Notification.MediaStyle style=new Notification.MediaStyle().setShowActionsInCompactView(0,1,2);if(token!=null)style.setMediaSession(token);return b.setStyle(style).build();}
 static boolean exists(Context c){for(android.service.notification.StatusBarNotification n:c.getSystemService(NotificationManager.class).getActiveNotifications())if(n.getId()==ID)return true;return false;}
 static void localRemoved(Context c){if(PlaybackService.instance==null)c.getSystemService(NotificationManager.class).cancel(ID);}
 static void refresh(Context c){if(PlaybackService.instance==null)c.getSystemService(NotificationManager.class).cancel(ID);}
}
